import sys

def input(str):
    length = len(str)
    insideParentheses = False
    wordCount = 0
    maxWordLength = 0
    currentWordLength = 0
    for i in range(length):
        ch = str[i]
        if ch == '(':
            if currentWordLength > 0:
                if currentWordLength > maxWordLength:
                    maxWordLength = currentWordLength
                currentWordLength = 0
            insideParentheses = True
        elif ch == ')':
            if currentWordLength > 0:
                wordCount += 1
                currentWordLength = 0
            insideParentheses = False
        elif ch == '_':
            if currentWordLength > 0:
                if insideParentheses:
                    wordCount += 1
                else:
                    if currentWordLength > maxWordLength:
                        maxWordLength = currentWordLength
                currentWordLength = 0
        else:
            currentWordLength += 1
    if currentWordLength > 0:
        if insideParentheses:
            wordCount += 1
        else:
            if currentWordLength > maxWordLength:
                maxWordLength = currentWordLength
    return str(maxWordLength) + " " + str(wordCount)

def main():
    lines = sys.stdin.read().splitlines()
    i = 0
    while i < len(lines):
        # Skip empty lines if any
        if lines[i].strip() == '':
            i += 1
            continue
        # Read and ignore the first line as per original code
        # and process the next line
        if i + 1 < len(lines):
            print(input(lines[i + 1]))
            i += 2
        else:
            break

if __name__ == "__main__":
    main()

